def count_first_elements(input_tuple):
    """
    Finds the number of elements that occur before the tuple element in the given tuple.

    Example:
    assert count_first_elements((1, 5, 7, (4, 6), 10) ) == 3
    """
    count = 0
    for element in input_tuple:
        if isinstance(element, tuple):
            for item in element:
                count += 1
        else:
            count += 1
    return count
```

