def freq_count(list1):
    """
    Get the frequency of all the elements in a list, returned as a dictionary.
    Example:
    assert freq_count([10,10,10,10,20,20,20,20,40,40,50,50,30])==({10: 4, 20: 4, 40: 2, 50: 2, 30: 1})
    """
    freq = {}
    for item in list1:
        if item in freq:
            freq[item] += 1
        else:
            freq[item] = 1
    return freq
```

