def is_samepatterns(arr1, arr2):
    """
    Check whether it follows the sequence given in the patterns array.
    Example: assert is_samepatterns(["red","green","green"], ["a", "b", "b"])==True
    """
    if len(arr1) != len(arr2):
        return False

    pattern_map = {}
    for i in range(len(arr1)):
        color = arr1[i]
        char = arr2[i]

        if color not in pattern_map:
            pattern_map[color] = char
        elif pattern_map[color] != char:
            return False

    return True
```

