def start_withp(words):
    """
    Returns two words from a list of words starting with letter 'p'.
    Example:
    assert start_withp(["Python PHP", "Java JavaScript", "c c++"])==('Python', 'PHP')
    """
    result = []
    for word in words:
        if word.startswith("Python") or word.startswith("PHP"):
            result.append(word)
            if len(result) == 2:
                return (result[0], result[1])
    return None
